//! UAX #29 — Unicode Text Segmentation: extended grapheme clusters (Unicode 18.0.0).
//!
//! Spec: https://www.unicode.org/reports/tr29/ — §3.1 boundary rules GB1–GB999 (extended clusters: GB9a, GB9b,
//! GB9c and GB11 included), §3.1.1 Hangul syllable sequences, and the Grapheme_Cluster_Break (Table 2),
//! Indic_Conjunct_Break (GB9c) and Extended_Pictographic properties. Property data lives in
//! `uax29_tables.rs`, generated by `tools/gen_uax29.py` from the UCD.
//!
//! Boundaries are reported as gap positions: gap `k` lies before the (k+1)-th character; gap 0 (GB1) and the
//! end of text (GB2) are always boundaries.

use crate::uax29_tables::RUNS;

/// Grapheme_Cluster_Break values (UAX #29 Table 2).
#[allow(clippy::upper_case_acronyms)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Gcb {
    Other,
    CR,
    LF,
    Control,
    Extend,
    ZWJ,
    RI,
    Prepend,
    SpacingMark,
    L,
    V,
    T,
    LV,
    LVT,
}

const GCB_ORDER: [Gcb; 14] = [
    Gcb::Other,
    Gcb::CR,
    Gcb::LF,
    Gcb::Control,
    Gcb::Extend,
    Gcb::ZWJ,
    Gcb::RI,
    Gcb::Prepend,
    Gcb::SpacingMark,
    Gcb::L,
    Gcb::V,
    Gcb::T,
    Gcb::LV,
    Gcb::LVT,
];

/// Indic_Conjunct_Break values used by GB9c.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InCb {
    None,
    Linker,
    Consonant,
    Extend,
}

/// Segmentation-relevant properties of one code point.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Props {
    pub gcb: Gcb,
    pub incb: InCb,
    pub ext_pict: bool,
}

/// Look up the segmentation properties of a code point.
pub fn props(cp: char) -> Props {
    let cp = cp as u32;
    let i = RUNS.partition_point(|&(start, _)| start <= cp) - 1;
    let p = RUNS[i].1;
    Props {
        gcb: GCB_ORDER[(p & 0xF) as usize],
        incb: match (p >> 4) & 0x3 {
            1 => InCb::Linker,
            2 => InCb::Consonant,
            3 => InCb::Extend,
            _ => InCb::None,
        },
        ext_pict: (p >> 6) & 1 == 1,
    }
}

/// Whether there is a grapheme cluster boundary at gap `g` (between `p[g-1]` and `p[g]`), per GB1–GB999.
fn boundary(p: &[Props], g: usize) -> bool {
    let n = p.len();
    // GB1: sot ÷ — always a boundary at the start of text.
    if g == 0 {
        return true;
    }
    // GB2: ÷ eot — always a boundary at the end of text.
    if g == n {
        return true;
    }
    let prev = p[g - 1];
    let next = p[g];
    // GB3: CR × LF.
    if prev.gcb == Gcb::CR && next.gcb == Gcb::LF {
        return false;
    }
    // GB4: (Control | CR | LF) ÷.
    if matches!(prev.gcb, Gcb::Control | Gcb::CR | Gcb::LF) {
        return true;
    }
    // GB5: ÷ (Control | CR | LF).
    if matches!(next.gcb, Gcb::Control | Gcb::CR | Gcb::LF) {
        return true;
    }
    // GB6–GB8: Hangul syllable sequences.
    if prev.gcb == Gcb::L && matches!(next.gcb, Gcb::L | Gcb::V | Gcb::LV | Gcb::LVT) {
        return false;
    }
    if matches!(prev.gcb, Gcb::LV | Gcb::V) && matches!(next.gcb, Gcb::V | Gcb::T) {
        return false;
    }
    if matches!(prev.gcb, Gcb::LVT | Gcb::T) && next.gcb == Gcb::T {
        return false;
    }
    // GB9, GB9a: × (Extend | ZWJ), × SpacingMark.
    if matches!(next.gcb, Gcb::Extend | Gcb::ZWJ | Gcb::SpacingMark) {
        return false;
    }
    // GB9b: Prepend ×.
    if prev.gcb == Gcb::Prepend {
        return false;
    }
    // GB9c: \p{InCB=Linker} \p{InCB=Extend}* × \p{InCB=Consonant}.
    if next.incb == InCb::Consonant {
        let mut j = g;
        while j > 0 && p[j - 1].incb == InCb::Extend {
            j -= 1;
        }
        if j > 0 && p[j - 1].incb == InCb::Linker {
            return false;
        }
    }
    // GB11: \p{Extended_Pictographic} Extend* ZWJ × \p{Extended_Pictographic}.
    if prev.gcb == Gcb::ZWJ && next.ext_pict {
        let mut k = g - 1;
        while k > 0 && p[k - 1].gcb == Gcb::Extend {
            k -= 1;
        }
        if k > 0 && p[k - 1].ext_pict {
            return false;
        }
    }
    // GB12, GB13: pairs of Regional Indicators; no break inside an unpaired-odd RI run.
    if prev.gcb == Gcb::RI && next.gcb == Gcb::RI {
        let mut k = 0;
        let mut j = g;
        while j > 0 && p[j - 1].gcb == Gcb::RI {
            k += 1;
            j -= 1;
        }
        if k % 2 == 1 {
            return false;
        }
    }
    // GB999: ÷ otherwise.
    true
}

/// Extended grapheme cluster boundaries of a character slice, as character indices.
/// Always starts with 0 and ends with `text.len()` (both for empty input: `[0]`).
pub fn boundaries_chars(text: &[char]) -> Vec<usize> {
    let p: Vec<Props> = text.iter().map(|&c| props(c)).collect();
    (0..=p.len()).filter(|&g| boundary(&p, g)).collect()
}

/// Extended grapheme clusters of a string, as byte offsets (start of each boundary-delimited cluster).
pub fn boundaries(s: &str) -> Vec<usize> {
    let chars: Vec<char> = s.chars().collect();
    let offsets: Vec<usize> = s.char_indices().map(|(b, _)| b).chain(std::iter::once(s.len())).collect();
    boundaries_chars(&chars).into_iter().map(|g| offsets[g]).collect()
}

/// Split a string into extended grapheme clusters.
pub fn graphemes(s: &str) -> Vec<&str> {
    let b = boundaries(s);
    b.windows(2).map(|w| &s[w[0]..w[1]]).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::uax29_tables::GCB_NAMES;

    #[test]
    fn gcb_order_matches_generated_table() {
        assert_eq!(GCB_ORDER.len(), GCB_NAMES.len());
        for (g, name) in GCB_ORDER.iter().zip(GCB_NAMES) {
            let dbg = format!("{g:?}");
            let want = if *name == "Regional_Indicator" { "RI" } else { *name };
            assert_eq!(dbg, want);
        }
    }

    #[test]
    fn family_emoji_is_one_cluster() {
        // man, ZWJ, woman, ZWJ, girl
        let s = "\u{1F468}\u{200D}\u{1F469}\u{200D}\u{1F467}";
        assert_eq!(graphemes(s).len(), 1);
    }

    #[test]
    fn flags_pair_up() {
        let s = "\u{1F1EF}\u{1F1F5}\u{1F1FA}\u{1F1F8}";
        assert_eq!(graphemes(s).len(), 2);
    }
}
